async ({ workspace: { read } }) => {
  const t = (await read("CHANGELOG.md", { format: "raw" })).content;
  const heads = [...t.matchAll(/^## \[(\d[^\]]*)\]/gm)].map((m) => m[1]).slice(0, 12);
  const defs = [...t.matchAll(/^\[([^\]]+)\]: (.*)$/gm)].slice(0, 8).map((m) => `${m[1]} ${m[2]}`);
  return { heads, defs };
}
